import { Component, input } from '@angular/core';
import { NzProgressModule } from 'ng-zorro-antd/progress';

export type HrmProgressStatus = 'success' | 'exception' | 'active' | 'normal';
export type HrmProgressType = 'line' | 'circle' | 'dashboard';

/** hrm-progress — bọc nz-progress (line/circle). */
@Component({
  selector: 'hrm-progress',
  imports: [NzProgressModule],
  template: `
    <nz-progress
      [nzPercent]="percent()"
      [nzStatus]="status()"
      [nzType]="type()"
      [nzSize]="size()"
      [nzSteps]="steps()"
      [nzShowInfo]="showInfo()"></nz-progress>
  `,
  host: { class: 'hrm-progress' },
})
export class HrmProgress {
  readonly percent = input(0);
  readonly status = input<HrmProgressStatus>('normal');
  readonly type = input<HrmProgressType>('line');
  readonly size = input<'default' | 'small'>('default');
  /** Chia thanh line thành N đoạn rời (0 = thanh liền). */
  readonly steps = input(0);
  readonly showInfo = input(true);
}
